Paso 5: tiempo de seguimiento

fecha_corte &lt;- ymd("2024-06-30")

registro |&gt;
  mutate(meses_seguimiento = time_length(interval(fecha_de_ingreso, fecha_corte), "months")) |&gt;
  summarise(mediana = median(meses_seguimiento),
            q1 = quantile(meses_seguimiento, .25), q3 = quantile(meses_seguimiento, .75)) |&gt;
  mutate(across(everything(), \(x) round(x, 1)))

